#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    int mid = n / 2;
    vector<int> first_half, second_half;

    function<void(int, int)> compute_sums1 = [&](int i, int total) {
        if (i == mid) {
            first_half.push_back(total);
        } else {
            compute_sums1(i + 1, (total + a[i]) % m);
            compute_sums1(i + 1, total);
        }
    };

    function<void(int, int)> compute_sums2 = [&](int i, int total) {
        if (i == n) {
            second_half.push_back(total);
        } else {
            compute_sums2(i + 1, (total + a[i]) % m);
            compute_sums2(i + 1, total);
        }
    };

    compute_sums1(0, 0);
    compute_sums2(mid, 0);

    sort(first_half.begin(), first_half.end());

    int result = 0;
    for (int val : second_half) {
        int target = m - val;
        auto it = lower_bound(first_half.begin(), first_half.end(), target);
        if (it != first_half.begin()) {
            int index = it - first_half.begin();
            int sum_candidate = first_half[index - 1] + val;
            if (sum_candidate > result) {
                result = sum_candidate;
            }
        }
    }

    cout << result << "\n";

    return 0;
}
